\label{cor:public}
For a fixed radius $\gamma\in(0,\gamma_{\max}]$, exact function evaluations, and $T\ge4N$, replace the adaptive batch rule by
\begin{equation}
 B_t^y=B_t^x=1+
 \lfloor \frac{(T-2N)t}{N(N+1)}\rfloor.
 \label{eq:public-batch}
\end{equation}
At most $T$ pairs, $2T$ values and $2N$ sequential rounds suffice, and
\begin{equation}
 \begin{aligned}
 \mathbb E[f(x_N)-f(x^\star)]
 \le \frac{h_0R^2}{2A_N}+\frac{16L_\gamma D^2}{N^2}+\frac{4\sqrt2\sigma_\gamma D}{\sqrt T}+M\gamma.
 \end{aligned}
 \label{eq:public-risk}
\end{equation}
The full proof is in Appendix~\ref{subsec:proof-public}.

\label{thm:paid}
For a fixed radius $\gamma\in(0,\gamma_{\max}]$ and exact function evaluations, Algorithm~\ref{alg:scalar} satisfies
\begin{align}
 \mathbb E[f(x_N)-f(x^\star)]
 \le \frac{h_0R^2}{2A_N}
 +\frac{16L_\gamma D^2}{N^2}
 \nonumber +\frac{8\sqrt2\sigma_\gamma D}{\sqrt T}
 +M\gamma. \label{eq:paid-risk}
\end{align}
No variance parameter enters the batch rule or the scalar update. The full proof is in Appendix~\ref{subsec:proof-paid}.

\label{thm:protected-main}
Under Assumptions~\ref{ass:geometry} and~\ref{ass:forward-moments}, assume uniform clean vector variance
$\sigma_0^2\le CdM_2^2$ for a fixed numerical constant $C\ge1$ and fixed spatial corruption $\|\delta\|_\infty\le\Delta$. Set $h_{\rm init}=h_{\rm ref}=h_0>0$. For an objective-error tolerance $\rho>0$, choose $g=c_d\Delta D/\rho\le\gamma_{\max}/2$. Algorithm~\ref{alg:protected-main} satisfies
\begin{equation}
 \begin{aligned}
 &\mathbb E[f(x_N)-f(x^\star)]\le\\
 &\widetilde O\!\Biggl(
 \frac{h_0D^2}{N^2}+\frac{\sqrt dM_2D}{\sqrt T}+M_2g\sqrt{\frac NT}+\rho\left(1+\sqrt{\frac dT}\right)+\Delta
 \\
 &+\min\!\Biggl\{L\left(\frac{D^2}{N^2}+g^2\right),\frac{d^{1/4}MD}{N}+\frac{\sqrt dMD^2}{\gamma_{\max} N^2}+Mg\Biggr\}\Biggr).
 \end{aligned}
 \label{eq:protected-main-order}
\end{equation}
The smooth branch requires $L$-smoothness on the evaluation domain; otherwise set $L=+\infty$. In each branch, $\widetilde O$ hides only the factor $1+\ell_{\mathrm{reg}}^\Delta$ of that branch. If $\Delta=0$, take $g=0$ and remove all $\rho$ terms. The method uses exactly $T$ pairs, $2T$ values and $N$ projections in $3N$ rounds with fixed batches or $5N$ rounds with adaptive batches. The full proof is in Appendix~\ref{subsec:proof-protected-main}.

\label{cor:protected-main-clean}
For exact evaluations, define
\begin{equation}
\begin{aligned}
 \mathcal B_{N,T}&=\frac{\sqrt dM_2D}{\sqrt T}+\min\!\left\{\frac{LD^2}{N^2},
 \frac{d^{1/4}MD}{N}+\frac{\sqrt dMD^2}{\gamma_{\max} N^2}\right\}.
 \label{eq:protected-main-base}
\end{aligned}
\end{equation}
If $\mathcal B_{N,T}>0$ and
$0<h_0\le N^2\mathcal B_{N,T}/(2D^2)$, then
$\mathbb E[f(x_N)-f(x^\star)]\le\widetilde O(\mathcal B_{N,T})$.
No positive problem-dependent lower bound on $h_0$ is imposed.
For any target $\varepsilon>0$, the choice made before sampling
$h_0\le\varepsilon N^2/(8D^2)$ makes the combined initialization and reference
cost at most $\varepsilon/4$.
The full proof is in Appendix~\ref{subsec:proof-protected-main-clean}.

\label{thm:joint-main}
Under Assumptions~\ref{ass:vector} and~\ref{ass:adaptive-moments} and exact projection onto the selected intersection, the execution on the selected ball satisfies
\begin{equation}
 \begin{aligned}
 &\mathbb E[f(x_N)-f(u)]\le\mathcal A_*(u)+\frac{4h_{\rm ref}S_2^2}{N^2}\\
 &\quad+\widetilde O\!\Biggl(\frac{\sigma_0S_2}{\sqrt T}
 +\min\!\Biggl\{\frac{LS_2^2}{N^2}+\frac{d^{1/4}M_2S_2}{\sqrt{NT}},\\
 &\qquad\frac{d^{1/4}MS_2}{N}
 +\frac{\sqrt d\,MS_2^2}{\gamma_{\max} N^2}
 +\frac{d^{1/4}M_2S_2}{\sqrt T}\Biggr\}\Biggr).
 \end{aligned}
 \label{eq:joint-main-order}
\end{equation}
Set $L=+\infty$ without population smoothness.
The notation $\widetilde O$ hides only universal constants and the
logarithmic factors specified in Appendix~\ref{subsec:proof-joint-main},
which also gives the exact bound.
Fixed batches require $T\ge16N$ and $3N+1$ rounds; adaptive batches require $T\ge32N$ and $5N+1$ rounds. Both use exactly $T$ pairs, $2T$ values and $N$ intersection projections, with no supplied $D,R,L,M,M_2$ or variance. The full proof is in Appendix~\ref{subsec:proof-joint-main}.

\label{lem:growth}
If each $\phi_t$ has gradient Lipschitz constant at most $L_\circ$, then
\begin{equation}
 [H_N-4L_\circ]_+^2\le[h_0-4L_\circ]_+^2
 +\frac{1}{D^2}\sum_{t=1}^Nt^2\lVert e_t^x-e_t^y\rVert^2.
 \label{eq:growth}
\end{equation}
Consequently, if
$W=\sum_{t=1}^N t^2\mathbb E\lVert e_t^x-e_t^y\rVert^2<\infty$, then
$\mathbb E(H_N-h_0)\le4L_\circ+\sqrt W/D$.

\label{cor:horizon}
For exact function evaluations, assume $\sigma_\gamma^2\le CdM_2^2$ and set
\begin{equation}
 \gamma=\min\{\gamma_{\max},d^{1/4}D/N\}.
 \label{eq:horizon-radius}
\end{equation}
The risk of Algorithm~\ref{alg:scalar} is at most
\begin{align}
 \frac{h_0R^2}{2A_N}
 &+\frac{17d^{1/4}MD}{N}
 +\frac{16\sqrt d\,MD^2}{\gamma_{\max} N^2}\nonumber\\
 &
 +\frac{8\sqrt{2Cd}\,M_2D}{\sqrt T}. \label{eq:horizon-risk}
\end{align}
For fixed batch sizes replace $8$ by $4$ in the final term.

\label{thm:stochastic-trajectory-potential}
Let $Q$ be convex with diameter at most $D>0$, let $h_0>0$, and let
$\phi$ be convex on $Q$ and differentiable at the points used in the
execution. Fix $x^0,u\in Q$ and $N\ge1$. Under the preceding trajectory,
predictability and conditional-mean assumptions, additionally assume that
$H_N$ and $\phi(x_N)-\phi(u)$ are integrable. Then all defined
$x_t,v_t,y_t$ belong to $Q$, $H_t\ge h_0$, and
\begin{equation}
 \mathbb E[\phi(x_N)-\phi(u)]\le
 \frac{h_0\lVert u-x^0\rVert^2/2+2D^2(\mathbb E H_N-h_0)}{A_N}.
 \label{eq:stochastic-trajectory-expected}
\end{equation}

\label{lem:paid-accounting}
Algorithm~\ref{alg:scalar} uses exactly $T$ pairs and $2T$
scalar values, $4N$ sequential sampling rounds, and $N$ projections. Moreover, $m_{\mathrm{sur}}\ge \mathsf U/4$ and $B_t^\iota\ge B_t^0\ge \mathsf U t/[4N(N+1)]$ for $\iota\in\{y,x\}$. At a fixed center, $\mathbb E[\widehat v_j\mid\text{history}]$ equals the single-record variance.

\label{thm:corruption}
Suppose the clean single-record variance is at most $\sigma_\gamma^2$ and
$\lVert \delta\rVert_\infty\le\Delta$. With
$c_d=d\mathbb E|[e]_1|\le\sqrt d$, where $[e]_1$ denotes the first
coordinate of $e$, Algorithm~\ref{alg:scalar} satisfies
\begin{equation}
 \mathbb E[f(x_N)-f(x^\star)]
 \le \frac{h_0R^2}{2A_N}+\frac{16L_\gamma D^2}{N^2}+M\gamma
 +\frac{16\sigma_\gamma D}{\sqrt T}
 +\frac{6c_dD\Delta}{\gamma}+\frac{16dD\Delta}{\gamma\sqrt T}.
 \label{eq:corruption-risk}
\end{equation}
All batch-selection and update costs remain as in Lemma~\ref{lem:paid-accounting}.

\label{thm:batch-variance-actual}
Let $e_t^y=g_t^y-\nabla\phi(y_t)$, $e_t^x=g_t^x-\nabla\phi(x_t)$, $A=A_N$, and let $u\in Q$ be fixed.
Then
\begin{equation}
 W:=\sum_{t=1}^Nt^2\mathbb E\|e_t^x-e_t^y\|^2
 =\mathbb E\sum_{j=1}^{2N}\frac{\omega_j^2V_j}{B_j}.
 \label{eq:batch-variance-exact}
\end{equation}
If $f\le\phi$ on $Q$ and $R_u=\|u-x^0\|$, then
\begin{align}
 \mathbb E[f(x_N)-f(u)]
 &\le\frac{h_0R_u^2}{2A}
 +\frac{2D^2(4L-h_0)_+}{A}
 +\phi(u)-f(u)+\frac{2D\sqrt W}{A}.
 \label{eq:batch-variance-risk}
\end{align}
For the adaptive batch rule with $T\ge8N$, $\mathsf U=T-4N$, and the reserve
\begin{equation}
 b_t=1+\left\lfloor
 \frac{(\mathsf U-2N)t}{2N(N+1)}
 \right\rfloor,
 \label{eq:batch-variance-reserve}
\end{equation}
define
\begin{equation}
 \overline{\mathcal V}_N
 =\frac1{2A}\mathbb E\sum_{j=1}^{2N}\omega_jV_j.
 \label{eq:batch-variance-average}
\end{equation}
Its actual counts satisfy
\begin{equation}
 W\le\frac{16A^2\overline{\mathcal V}_N}{\mathsf U}.
 \label{eq:batch-variance-paid-energy}
\end{equation}
Consequently the variance term in \eqref{eq:batch-variance-risk} is at
most $8D\sqrt{\overline{\mathcal V}_N/\mathsf U}$.
The complete execution uses exactly $T$ sampled functions and $2T$ values,
uses $4N$ sequential sampling stages, and performs $N$ projections.

\label{prop:batch-variance-paid-limit}
For $N\ge2$, $T\ge8N$, and positive $h_0,s_0$, put
$\mathfrak R_{\mathrm{batch}}=1+S_{\mathrm{sur}}/b_1$.
Every actual trajectory satisfies
\begin{equation}
 \sum_jv_j/B_j
 \le\mathfrak R_{\mathrm{batch}}\mathcal C_\star^{\mathrm{tr}}(v).
 \label{eq:batch-variance-paid-upper}
\end{equation}
There are convex
affine populations on a compact one-dimensional domain, a global iid
sample-function law with a finite-second-moment Lipschitz envelope,
and a legal fixed-radius two-value record such that
\begin{equation}
 \frac{\mathbb E\sum_jv_j/B_j}
      {\mathbb E\mathcal C_\star^{\mathrm{tr}}(v)}
 \ge\frac{\mathfrak R_{\mathrm{batch}}}{2}
 \ge\frac12+\min\left\{\frac{\mathsf U}{16},
                         \frac{N(N+1)}8\right\}.
 \label{eq:batch-variance-paid-loss}
\end{equation}
There is a sequence of these laws, with the same population and a
uniformly bounded second-moment envelope, for which
\begin{equation}
 \lim_{p\downarrow0}
 \frac{\mathbb E\sum_jv_j/B_j}
      {\mathbb E\mathcal C_\star^{\mathrm{tr}}(v)}
 =\mathfrak R_{\mathrm{batch}}.
 \label{eq:batch-variance-paid-limit}
\end{equation}
Thus $\mathfrak R_{\mathrm{batch}}$ is the exact supremum of the ratio
in this oracle class, allowing the compact domain and legal radius
to vary in the matching construction. It satisfies
\begin{equation}
 1+\min\left\{\frac{\mathsf U}8,\frac{N(N+1)}4\right\}
 \le\mathfrak R_{\mathrm{batch}}
 \le1+\min\{\mathsf U,4N(N+1)\}.
 \label{eq:batch-variance-paid-scale}
\end{equation}
It equals $1+2N$ when $T=8N$, and converges to $1+N(N+1)$ as
$\mathsf U\to\infty$ at fixed $N$.
The numerator is exactly $W$ in \eqref{eq:batch-variance-exact}.

\label{lem:smoothing-accounting}
The specified execution uses exactly $T$ original pairs, $2T$ scalar values, $5N$ sequential stochastic stages, and $N$ projections. Its radii are nonincreasing and lie in $[\underline\gamma,\bar\gamma]$. Each clean update mean is conditionally unbiased for the gradient of its selected smoothed objective at its chosen center. Moreover,
\begin{equation}
 B_j\ge B_t^0\ge\frac{\mathsf U t}{4N(N+1)},\qquad \mathsf U\ge T/2.
 \label{eq:radius-batch-lower-app}
\end{equation}

\label{lem:secant-growth}
For every execution,
\begin{align}
 H_N&\le\mathcal C_N+
       \sqrt{\mathcal C_N^2+h_0^2+2\mathcal E_N/D^2},
       \label{eq:secant-growth-exact}\\
 H_N-h_0&\le2\mathcal C_N+\sqrt{2\mathcal E_N}/D.
       \label{eq:secant-growth-simple}
\end{align}
If all targets are $L_*$-smooth, then also
\begin{equation}
 H_N-h_0\le4L_*+\sqrt{\mathcal E_N}/D.
 \label{eq:secant-growth-uniform}
\end{equation}

\label{thm:radial-clean}
Assume the uniform clean vector moment assumptions, the radial moment conditions
of Lemma~\ref{lem:radial-moment}, and integrability of the displayed
potential. For any $\tau,\Gamma$ in Algorithm~\ref{alg:radial} and fixed
$u\in Q$, its clean expected risk satisfies
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&\frac{h_0R_u^2}{2A_N}
 +\frac{8D^2}{A_N}\min\{L_{\rm pop},\sqrt dM\mathfrak X_0\}
 \nonumber\\
 &+\frac{8\sqrt2\sigma_0D}{\sqrt T}+\tau+\eta_{\mathrm{rad}}.
 \label{eq:radial-main-risk}
\end{align}
The method spends exactly $T$ pairs, $2T$ values and $5N$ sequential
sampling stages, with $N$ projections. The full proof is in
Appendix~\ref{subsec:proof-radial-clean}.

\label{lem:radial-affine}
For $y\in Q$ and $0<\gamma\le\gamma_{\max}$, the derivative in
\eqref{eq:radial-function} exists, and
\begin{align}
 h_\gamma(y)
 &=d\bigl[\mathbb E_e f(y+\gamma e)-f_\gamma(y)\bigr],
 &0\le h_\gamma(y)&\le M\mu_d\gamma,
 \label{eq:radial-boundary}\\
 f(u)&\ge f_\gamma(y)+
       \langle \nabla f_\gamma(y),u-y\rangle-h_\gamma(y)
 &&(u\in Q),\label{eq:radial-affine}\\
 h_{\lambda\gamma}(y)&\le\lambda h_\gamma(y)
 &&(0<\lambda\le1).
 \label{eq:radial-shrink}
\end{align}
If $f$ is differentiable and $L$-smooth on the evaluation domain, then also
\begin{equation}
 h_\gamma(y)\le L\nu_d\gamma^2.
 \label{eq:radial-smooth-charge}
\end{equation}

\label{lem:radial-moment}
Under either sufficient regularity condition above,
\begin{equation}
 \mathbb E J_\gamma(y)=h_\gamma(y),\qquad
 \mathbb E J_\gamma(y)^2\le\chi_dM_2^2\gamma^2.
 \label{eq:radial-record-moment}
\end{equation}
For a mean $\widehat h^{\,0}$ of $B$ clean records at a
center and radius fixed by the preceding history, with functions and
directions sampled independently of that history and of one another,
\begin{equation}
 \mathbb E[\widehat h^{\,0}\mid\mathcal F]=h_\gamma(y),\qquad
 \mathbb E[|\widehat h^{\,0}-h_\gamma(y)|^2\mid\mathcal F]
 \le\chi_dM_2^2\gamma^2/B.
 \label{eq:radial-mean-moment}
\end{equation}
The corruption contribution to a radial record or its mean has
absolute value at most $2d\Delta$.

\label{lem:radial-counts}
The method uses exactly $T$ original pairs, $2T$ scalar values,
$5N$ sequential sampling stages and $N$ projections. It satisfies
\begin{equation}
 B^{\mathrm{rad}}\ge\frac{T}{16N},\qquad
 \mathsf U\ge\frac{5T}{8}\ge\frac T2,\qquad
 B_t^\iota\ge B_t^0\ge\frac{\mathsf U t}{4N(N+1)},\quad \iota\in\{y,x\}.
 \label{eq:radial-floors}
\end{equation}

\label{thm:radial-potential}
The scalar projection and curvature update satisfy
\begin{align}
 A_N[f(x_N)-f(u)]\le{}&h_0R_u^2/2+2D^2(H_N-h_0)
 +\sum_ta_th_{\gamma_t}(y_t)+\sum_tZ_t(u)\nonumber\\
 &+\mathcal D_N-A_N[f_{\gamma_N}(x_N)-f(x_N)].
 \label{eq:radial-potential}
\end{align}
The last line can be replaced by $\mathcal D_N^+$.
For nonincreasing radii this term can be omitted. For arbitrary
radii,
\begin{align}
 \mathcal D_N^+&\le M\mu_d\sum_{t<N}A_t
                            [\gamma_{t+1}-\gamma_t]_+,
 \label{eq:radial-lipschitz-drift}\\
 \mathcal D_N^+&\le\frac{L\nu_d}{2}\sum_{t<N}A_t
                            [\gamma_{t+1}^2-\gamma_t^2]_+
 \label{eq:radial-smooth-drift}
\end{align}
in the Lipschitz and smooth cases respectively.

\label{lem:radial-radius}
The rule \eqref{eq:radial-policy} satisfies
\begin{equation}
 \mathbb E h_{\gamma_t}(y_t)\le\tau+2d\Delta+\eta_{\mathrm{rad}}.
 \label{eq:radial-selected-charge}
\end{equation}
If $2d\Delta<\tau$, define
\begin{equation}
 \tau_- =\tau-2d\Delta,\qquad
 \mathfrak X=\Gamma^{-1}+(M+\omega_{\mathrm{rad}})/\tau_-.
 \label{eq:radial-reciprocal-scale}
\end{equation}
Then, pathwise and in expectation respectively,
\begin{align}
 X_N&\le\max\{\Gamma^{-1},
                    \max_{t\le N}[\mathsf s_t]_+/\tau_-\},
 \label{eq:radial-reciprocal-path}\\
 \mathbb E X_N&\le\mathfrak X,\qquad
 (\mathbb E X_N^2)^{1/2}\le\mathfrak X.
 \label{eq:radial-reciprocal-moment}
\end{align}
For clean observations these statements hold for every $\tau>0$
with $\tau_- =\tau$. Moreover
\begin{equation}
 \omega_{\mathrm{rad}}\le4\sqrt2M_2N/\sqrt T,
 \qquad\eta_{\mathrm{rad}}\le
                   4\sqrt2M_2\Gamma\sqrt N/\sqrt T.
 \label{eq:radial-public-moment-scales}
\end{equation}

\label{thm:radial-corruption}
Suppose $2d\Delta<\tau$ and use
\eqref{eq:radial-reciprocal-scale}. Under the uniform clean vector
variance bound $\sigma_0^2$ and the radial sample regularity,
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&\frac{h_0R_u^2}{2A_N}
 +\frac{8D^2}{A_N}
       \min\{L_{\mathrm{pop}},\sqrt dM\mathfrak X\}
 \nonumber\\
 &+\tau+2d\Delta+\eta_{\mathrm{rad}}
           +6c_dD\Delta\mathfrak X\nonumber\\
 &+\frac{16\sigma_0D}{\sqrt T}
       +\frac{16dD\Delta\mathfrak X}{\sqrt T},
 \label{eq:radial-corrupt-risk}
\end{align}
where $c_d=d\mathbb E_e|[e]_1|\le\sqrt d$.

\label{lem:threshold-accounting}
Algorithm~\ref{alg:threshold} spends exactly $T$ pairs, $2T$ values
and $N$ projections. It uses $3N$ sequential sampling stages with fixed
batch sizes and $5N$ with adaptive batch sizes. Moreover
\begin{align}
 \frac{\sqrt{\mathbb E\mathcal E_N}}D
 &\le\frac{c_{\rm vec}\sigma_0A_N}{D\sqrt T},
 \label{eq:threshold-energy}\\*
 \omega_{\rm rad}&\le4\sqrt2M_2N/\sqrt T,&
 \eta_{\rm rad}&\le
 \frac{4\sqrt2d^{1/4}M_2D}{\sqrt N\sqrt T},
 \label{eq:threshold-public-moments}\\*
 \mathbb E\mathsf S_N&\le M+\omega_{\rm rad},&
 (\mathbb E\mathsf S_N^2)^{1/2}&\le M+\omega_{\rm rad}.
 \label{eq:threshold-slope-moments}
\end{align}
Conditionally on the history $\mathcal F_t^{\rm rad}$ before its
radial stage,
\begin{equation}
 \mathbb E[h_{\gamma_t}(y_t)\mid\mathcal F_t^{\rm rad}]
 \le\tau_t+\eta_{\rm rad}.
 \label{eq:threshold-local-charge}
\end{equation}

\label{lem:threshold-reference}
For every iteration,
\begin{align}
 \underline K_t&\le\mathsf K_{t-1}<2\underline K_t,&
 \gamma_t^{-1}&\le
 \max\{\Gamma^{-1},\mathsf S_NN^2/(\underline K_tD^2)\},
 \label{eq:threshold-reciprocal}\\
 L_t&\le\frac{\sqrt dM}{\Gamma}
 +\frac{2\sqrt dM\mathsf S_NN^2}{\mathsf K_{t-1}D^2},
 \label{eq:threshold-smoothness}
\end{align}
where $L_t$ is a valid smoothness bound for the selected target.
If $J=\sum_t I_t$, then
\begin{equation}
 J\le\log_2\!\left(1+\frac{H_N-h_{\rm init}}{h_{\rm ref}}\right),
 \qquad
 \sum_{t:I_t=1}\underline K_t\le2(H_N-h_{\rm init}).
 \label{eq:threshold-geometric}
\end{equation}

\label{lem:threshold-growth}
Pathwise,
\begin{equation}
 H_N-h_{\rm init}\le
 (\mathfrak H+2NM/D-h_{\rm ref})_+
                         +\sqrt{\mathcal E_N}/D.
 \label{eq:threshold-growth-path}
\end{equation}
Consequently $\mathbb E(H_N-h_{\rm init})\le\mathcal H_{\rm ns}$.
For an $L$-smooth population it is also at most $\mathcal H_{\rm s}$.

\label{lem:threshold-drift}
Let
$\mathcal D_N^+=\sum_{t=2}^N A_{t-1}
[\phi_t(x_{t-1})-\phi_{t-1}(x_{t-1})]_+$.
Then
\begin{equation}
 \frac{\mathbb E\mathcal D_N^+}{A_N}
 \le\frac{2D^2}{N^2}\mathbb E(H_N-h_{\rm init})
 +\eta_{\rm rad}\mathbb E J+\frac{2MDN}{A_N}\mathbb E J.
 \label{eq:threshold-drift-bound}
\end{equation}
For an $L$-smooth population replace the last term by
$LD^2\mathbb E J/A_N$.

\label{cor:threshold-smooth}
If the population is $L$-smooth, put
$\ell_{\rm s}=\log_2(1+\mathcal H_{\rm s}/h_{\rm ref})$. Then
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&
 \frac{\mathbb E[h_{\rm init}R_u^2]}{2A_N}
 +\frac{[(28+2\ell_{\rm s})L+h_{\rm ref}]D^2}{N^2}
 \nonumber\\
 &+\frac{5c_{\rm vec}\sigma_0D}{\sqrt T}
 +\frac{4\sqrt2(1+\ell_{\rm s})d^{1/4}M_2D}
             {\sqrt N\sqrt T}.
 \label{eq:threshold-smooth-risk}
\end{align}
With $h_{\rm init}=h_{\rm ref}=h_0$ and
$\sigma_0^2\le CdM_2^2$, the order is
$\widetilde O((L+h_0)D^2/N^2+\sqrt dM_2D/\sqrt T)$.
Only the displayed logarithm is suppressed.

\label{cor:threshold-nonsmooth}
Put $\ell_{\rm ns}=\log_2(1+\mathcal H_{\rm ns}/h_{\rm ref})$.
Then
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&
 \frac{\mathbb E[h_{\rm init}R_u^2]}{2A_N}
 +\frac{h_{\rm ref}D^2}{N^2}
 +[(42+14\sqrt2)d^{1/4}+4\ell_{\rm ns}]\frac{MD}{N}\nonumber\\
 &+\frac{28\sqrt dMD^2}{\gamma_{\max} N^2}
 +\frac{5c_{\rm vec}\sigma_0D}{\sqrt T}
 +\frac{56d^{1/4}M_2D}{\sqrt T}\nonumber\\
 &+\frac{4\sqrt2(1+\ell_{\rm ns})d^{1/4}M_2D}
             {\sqrt N\sqrt T}.
 \label{eq:threshold-nonsmooth-risk}
\end{align}
If $h_{\rm init}=h_{\rm ref}=h_0$,
$\gamma_{\max}\ge d^{1/4}D/N$ and $\sigma_0^2\le CdM_2^2$, the
same controller has order
$\widetilde O(h_0D^2/N^2+d^{1/4}MD/N+\sqrt dM_2D/\sqrt T)$.

\label{lem:corrupt-forward-secant}
Draw a uniform-ball $U$ independently of the sampled function indexed by $\xi$.
For $0<\gamma\le\gamma_{\max}/2$, put
\begin{align}
 q_\gamma(y)&=f_{2\gamma}(y)-f_\gamma(y),\nonumber\\
 \widehat q_\gamma^0(y;U,\xi)
 &=F(y+2\gamma U,\xi)-F(y+\gamma U,\xi).
 \label{eq:corrupt-forward-record}
\end{align}
Then
\begin{equation}
 0\le h_\gamma(y)\le q_\gamma(y)\le\mu_dM\gamma.
 \label{eq:corrupt-forward-charge}
\end{equation}
Under the weak-gradient and segment-integrability hypotheses of
Lemma~\ref{lem:oracle-moments}, or a random sample Lipschitz envelope
with second moment at most $M_2^2$, the record satisfies
\begin{equation}
 \mathbb E \widehat q_\gamma^0(y)=q_\gamma(y),\qquad
 \mathbb E\bigl[\widehat q_\gamma^0(y)^2\bigr]\le\nu_dM_2^2\gamma^2.
 \label{eq:corrupt-forward-moment}
\end{equation}
The corrupted record $\widehat q_\gamma$ differs pointwise from $\widehat q_\gamma^0$
by at most $2\Delta$. For $0<\lambda\le1$,
\begin{equation}
 h_{\lambda\gamma}(y)\le\lambda q_\gamma(y).
 \label{eq:corrupt-forward-shrink}
\end{equation}
The affine lower model for every original comparator $u\in Q$ remains
\begin{equation}
 f(u)\ge f_\gamma(y)+\langle \nabla f_\gamma(y),u-y\rangle-h_\gamma(y).
 \label{eq:corrupt-original-model}
\end{equation}
If the population is $L$-smooth on the evaluation domain, then
$h_\gamma(y)\le L\nu_d\gamma^2$.

\label{lem:corrupt-controller}
Algorithm~\ref{alg:corrupt-radial} uses exactly $T$ pairs and $2T$
values, $N$ projections, and $3N$ sampling stages with fixed batch sizes or $5N$ with adaptive batch sizes. Its diagnostic and radius satisfy
\begin{align}
 \|\mathsf S_N\|_{L_2}&\le\mu_dM+\omega,
 &\mathbb E\mathsf S_N&\le\mu_dM+\omega,
 \label{eq:corrupt-diagnostic-maximum}\\
 \gamma_t^{-1}
 &\le\min\{g^{-1},
        \max\{\Gamma^{-1},\mathsf S_NN^2/(\underline K_tD^2)\}\},
 \label{eq:corrupt-inverse-path}\\
 \left\|\max_t\gamma_t^{-1}\right\|_{L_2}&\le\zeta.
 \label{eq:corrupt-inverse-moment}
\end{align}
If $J=\sum_t I_t$, then
\begin{equation}
 J\le\log_2\left(1+\frac{H_N-h_{\rm init}}{h_{\rm ref}}\right),
 \qquad
 \sum_{t:I_t=1}\underline K_t\le2(H_N-h_{\rm init}).
 \label{eq:corrupt-reference-cost}
\end{equation}

\label{lem:corrupt-vector-energy}
The actual corrupted vector means satisfy
\begin{equation}
 \frac{\sqrt{\mathbb E\mathcal E_N}}D
 \le\frac{c_{\rm vec}\bar\sigma A}{D\sqrt T}
            +\frac{2\beta\sqrt{\mathsf W_{N,2}}}D,
 \qquad
 \frac1A\left|\mathbb E\sum_tZ_t\right|\le2D\beta.
 \label{eq:corrupt-vector-energy}
\end{equation}

\label{lem:corrupt-local-charge}
Conditionally on the history before the radial stage,
\begin{equation}
 \mathbb E[h_{\gamma_t}(y_t)\mid\mathcal F_t^{\rm rad}]
 \le\tau_t+\eta+4\Delta+w_{\mathrm{reg}}.
 \label{eq:corrupt-local-charge}
\end{equation}

\label{lem:corrupt-growth-drift}
For either applicable case $\mathrm{reg}$,
$\mathbb E(H_N-h_{\rm init})\le\mathcal H^\Delta_{\mathrm{reg}}$ and $\mathbb E J\le\ell_{\mathrm{reg}}^\Delta$.
For
\[
 \mathcal D_N^+=\sum_{t=2}^NA_{t-1}
 [f_{\gamma_t}(x_{t-1})-f_{\gamma_{t-1}}(x_{t-1})]_+,
\]
one has
\begin{equation}
 \frac{\mathbb E\mathcal D_N^+}A
 \le\frac{2D^2}{N^2}\mathcal H^\Delta_{\mathrm{reg}}
                      +(\eta+4\Delta+w_{\mathrm{reg}}+q_{\mathrm{reg}})\ell_{\mathrm{reg}}^\Delta.
 \label{eq:corrupt-drift}
\end{equation}

\label{thm:corrupt-radial}
Under the stated geometry, clean moment and fixed-corruption assumptions,
Algorithm~\ref{alg:corrupt-radial} satisfies, for every fixed $u\in Q$,
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&
 \frac{\mathbb E[h_{\rm init}R_u^2]}{2A}
 +k_ND^2\mathcal H^\Delta_{\mathrm{reg}}+\frac{h_{\rm ref}D^2}{N^2}\nonumber\\
 &+(\eta+4\Delta+w_{\mathrm{reg}})(1+\ell_{\mathrm{reg}}^\Delta)+q_{\mathrm{reg}}\ell_{\mathrm{reg}}^\Delta+2D\beta,
 \label{eq:corrupt-adaptive-risk}
\end{align}
where $R_u=\lVert u-x^0\rVert$ and the quantities are
\eqref{eq:corrupt-diagnostic-scales}--\eqref{eq:corrupt-curvature-envelopes}.
The nonsmooth branch is always applicable; the smooth branch additionally
assumes population $L$-smoothness on the evaluation domain. The exact counts are
$T$ original pairs, $2T$ values and $N$ projections in $3N$ sequential sampling stages with fixed batch sizes or
$5N$ with adaptive batch sizes.

\label{cor:corrupt-bias-budget}
Fix $\rho>0$. Choose
\begin{equation}
 g=\frac{c_d\Delta D}{\rho}\le\gamma_{\max}/2.
 \label{eq:corrupt-public-floor}
\end{equation}
For $\Delta>0$,
$D\beta\le\rho$ and
$\bar\sigma\le\sigma_0+\kappa_d\rho/D$.
The following explicit bounds hold, with the actual applicable
$\ell_{\mathrm{reg}}^\Delta$ of \eqref{eq:corrupt-curvature-envelopes}:
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&
 \frac{\mathbb E[h_{\rm init}R_u^2]}{2A}
 +\frac{[(28+2\ell_{\rm s}^\Delta)L+h_{\rm ref}]D^2}{N^2}
 +\frac{5c_{\rm vec}\sigma_0D}{\sqrt T}\nonumber\\
 &+\left(2+\frac{14}{\sqrt N}
              +\frac{5c_{\rm vec}\kappa_d}{\sqrt T}\right)\rho
 +(\eta+4\Delta+\nu_dLg^2)(1+\ell_{\rm s}^\Delta)
 \label{eq:corrupt-smooth-explicit}
\end{align}
in the smooth case, and
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&
 \frac{\mathbb E[h_{\rm init}R_u^2]}{2A}
 +\frac{h_{\rm ref}D^2}{N^2}
 +\frac{56c_dMD^2}{\gamma_{\max} N^2}\nonumber\\
 &+\left(\frac{28c_d}{d^{1/4}}+14\sqrt{2c_d}
                       +14+4\ell_{\rm ns}^\Delta\right)\frac{MD}{N}
 +\frac{5c_{\rm vec}\sigma_0D}{\sqrt T}\nonumber\\
 &+\frac{28\sqrt{2c_d}M_2D}{\sqrt T}
 +\left(2+\frac{14}{\sqrt N}
            +\frac{5c_{\rm vec}\kappa_d}{\sqrt T}\right)\rho\nonumber\\
 &+(\eta+4\Delta+\mu_dMg)(1+\ell_{\rm ns}^\Delta)
 \label{eq:corrupt-nonsmooth-explicit}
\end{align}
generally. The diagnostic scale obeys
\begin{equation}
 \eta\le4\sqrt{\nu_d}M_2
 \left(\frac{d^{1/4}D}{\sqrt N\sqrt T}
                         +g\sqrt{N/T}\right).
 \label{eq:corrupt-floor-diagnostic-cost}
\end{equation}
When $\Delta=0$, take $g=0$; then $\beta=0$ and
$\bar\sigma=\sigma_0$, and all displayed $\rho$ terms may be removed.

\label{cor:corrupt-accuracy}
Fix $\varepsilon>0$ and choose $\rho=\varepsilon/64$ in
\eqref{eq:corrupt-public-floor}. Suppose $\mathcal C_{\mathrm{reg}}\le\varepsilon/2$,
the appropriate mode budget holds, and
\begin{equation}
 T\ge\left(\frac{5c_{\rm vec}\kappa_d}{4}\right)^2,
 \qquad
 \Delta\le\frac{\varepsilon\gamma_{\max}}{128c_dD},
 \qquad
 \Delta\le\frac{\varepsilon}{64(1+\ell_{\mathrm{reg}}^\Delta)}.
 \label{eq:corrupt-accuracy-common}
\end{equation}
In the nonsmooth branch additionally assume
\begin{equation}
 \Delta\le
 \frac{\varepsilon^2}
 {1024c_d\mu_dMD(1+\ell_{\rm ns}^\Delta)}.
 \label{eq:corrupt-accuracy-nonsmooth}
\end{equation}
In the smooth branch this condition may instead be replaced by
\begin{equation}
 \Delta\le
 \frac{\varepsilon^{3/2}}
 {256c_dD\sqrt{\nu_dL(1+\ell_{\rm s}^\Delta)}}.
 \label{eq:corrupt-accuracy-smooth}
\end{equation}
A constraint with zero $M$ or zero $L$ in its denominator is omitted
because the corresponding floor charge is zero. Then
$\mathbb E[f(x_N)-f(u)]\le\varepsilon$, with the exact costs of
Theorem~\ref{thm:corrupt-radial}.

\label{lem:epsilon-clean-scales}
For $\Delta=0$ and $g=0$, the envelopes and diagnostic scales of
Theorem~\ref{thm:corrupt-radial} satisfy
\begin{align}
 \mathcal H^\Delta_{\rm s}D^2/N^2
   &\le4r_{\rm s}+6r_{\rm st}\le6\mathcal B_{\rm s},\nonumber\\
 \mathcal H^\Delta_{\rm ns}D^2/N^2
   &\le(6+2\sqrt2)r_{\rm ns}+8a_{\rm ns}+6r_{\rm st}
    \le9\mathcal B_{\rm ns},\nonumber\\
 \eta&\le4r_{\rm st},\qquad
 q_{\rm s}\le2r_{\rm s},\qquad
 q_{\rm ns}\le4r_{\rm ns}.
 \label{eq:epsilon-clean-scales}
\end{align}
They hold in both batch modes, including the integer floors and
residual allocation in the stated execution.

\label{thm:epsilon-clean}
Under the clean-oracle assumptions and initialization
\eqref{eq:epsilon-initialization}, define
\begin{equation}
 \lambda_{\rm s}^\varepsilon=\log_2\left(1+
             \frac{6\mathcal B_{\rm s}}{\theta\varepsilon}\right),
 \qquad
 \lambda_{\rm ns}^\varepsilon=\log_2\left(1+
             \frac{9\mathcal B_{\rm ns}}{\theta\varepsilon}\right).
 \label{eq:epsilon-calibrated-logs}
\end{equation}
For every fixed original comparator $u\in Q$, the same execution
satisfies every applicable branch of
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&2\theta\varepsilon
    +(28+2\lambda_{\rm s}^\varepsilon)r_{\rm s}
    +(46+4\lambda_{\rm s}^\varepsilon)r_{\rm st},
 \label{eq:epsilon-clean-smooth}\\
 \mathbb E[f(x_N)-f(u)]\le{}&2\theta\varepsilon
    +(42+14\sqrt2+4\lambda_{\rm ns}^\varepsilon)r_{\rm ns}
    +56a_{\rm ns}+(46+4\lambda_{\rm ns}^\varepsilon)r_{\rm st}.
 \label{eq:epsilon-clean-nonsmooth}
\end{align}
The counts remain exactly $T$ two-value pairs, $2T$ values and $N$
projections in $3N$ sampling stages with fixed batch sizes or $5N$ with adaptive batch sizes.

\label{cor:epsilon-clean-budgets}
Choose the initialization before sampling
\begin{equation}
 h_0=h_{\rm ref}=\frac{4\varepsilon N^2}{77D^2}.
 \label{eq:epsilon-initialization-77}
\end{equation}
If an applicable population budget satisfies
$\mathcal B_{\mathrm{reg}}\le\varepsilon/77$, then
$\mathbb E[f(x_N)-f(u)]<\varepsilon$ for every fixed $u\in Q$.
In particular, sufficient smooth budgets are
\begin{equation}
 N\ge\max\{1,\sqrt{154}\,D\sqrt{L/\varepsilon}\},
 \qquad
 T\ge\left(
  \frac{154(\sigma_0+\sqrt dM_2)D}{\varepsilon}\right)^2,
 \label{eq:epsilon-explicit-smooth-budgets}
\end{equation}
in addition to the appropriate mode condition. Sufficient nonsmooth
budgets are
\begin{align}
 N\ge\max\left\{1,
   \frac{231d^{1/4}MD}{\varepsilon},
   \sqrt{231}\,d^{1/4}D
                     \sqrt{\frac M{\gamma_{\max}\varepsilon}}\right\},
 \qquad
 T\ge\left(
   \frac{231(\sigma_0+\sqrt dM_2)D}{\varepsilon}\right)^2.
 \label{eq:epsilon-explicit-nonsmooth-budgets}
\end{align}
Thus the sufficient orders contain no adaptation logarithm:
\begin{align}
 N_{\rm s}&=O\left(1+D\sqrt{L/\varepsilon}\right),\nonumber\\
 N_{\rm ns}&=O\left(1+\frac{d^{1/4}MD}{\varepsilon}
       +d^{1/4}D\sqrt{\frac M{\gamma_{\max}\varepsilon}}\right),\nonumber\\
 T&=O\left(N+
       \frac{(\sigma_0^2+dM_2^2)D^2}{\varepsilon^2}\right).
 \label{eq:epsilon-clean-complexities}
\end{align}
These are sufficient conditions on budgets fixed before sampling. Accuracy is
interpreted through the population risk bound for the supplied horizon.

\label{cor:epsilon-corruption-budgets}
Initialize by \eqref{eq:epsilon-initialization-77}, choose before sampling the
bias allowance $\rho=\varepsilon/64$, and supply $\Delta\ge0$.
Choose
\begin{equation}
 g=\frac{64c_d\Delta D}{\varepsilon},\qquad
 \Gamma=\max\{g,\Gamma_0\}.
 \label{eq:epsilon-corruption-floor}
\end{equation}
Let $\kappa_d=d/c_d$. In addition to the mode condition, assume
\begin{align}
 \mathcal B_{\mathrm{reg}}&\le\varepsilon/256,
 &T&\ge(5c_{\rm vec}\kappa_d/4)^2,\nonumber\\
 \Delta&\le\frac{\varepsilon\gamma_{\max}}{128c_dD},
 &\Delta&\le\varepsilon/160,\nonumber\\
 T&\ge\frac{25600\nu_dM_2^2g^2N}{\varepsilon^2}.
 \label{eq:epsilon-corruption-common}
\end{align}
In the nonsmooth branch additionally assume
\begin{equation}
 \Delta\le\frac{\varepsilon^2}{2560c_d\mu_dMD};
 \label{eq:epsilon-corruption-nonsmooth}
\end{equation}
in the smooth branch it suffices instead that
\begin{equation}
 \Delta\le\frac{\varepsilon^{3/2}}
                  {64\sqrt{40}\,c_dD\sqrt{\nu_dL}}.
 \label{eq:epsilon-corruption-smooth}
\end{equation}
A condition with $M=0$ or $L=0$ in its denominator is omitted.
Then, for every fixed $u\in Q$,
\begin{equation}
 \mathbb E[f(x_N)-f(u)]
   <\left(\frac8{77}+\frac{49}{64}\right)\varepsilon
   <\varepsilon,
 \label{eq:epsilon-corruption-risk}
\end{equation}
with exactly the same pair, value, projection and stage counts.
The reference logarithm satisfies $\ell_{\mathrm{reg}}^\Delta<3/2$.

\label{lem:frontier-conditional}
Under the preceding assumptions, set $\nu=8\sqrt2$ for fixed
batch sizes and $\nu=16\sqrt2$ for adaptive batch sizes. Then
\begin{align}
 \mathbb E[\phi(x_N)-\phi(u_S)\mid\text{anchor}]
 \le{}&\frac{h_{\rm a}\min\{R_u^2,S^2\}}{2A}
 +\frac{32L_\gamma S^2}{A}
 +\frac{\nu\sigma_\gamma S}{\sqrt{T'}}.
 \label{eq:frontier-conditional-risk}
\end{align}

\label{cor:frontier-noise-multiplier}
Under Theorem~\ref{thm:run5-distance-fixed}, with
$\gamma_{\rm a}=\gamma$ and $\sigma_{\rm a}=\sigma_\gamma$, define
\begin{equation}
 \mathcal H_p(R)=R+r_0+R^2/(p r_0),\qquad
 P_{\rm up}(p)=\sqrt3+\nu\sqrt2(1+2p).
 \label{eq:frontier-noise-shape}
\end{equation}
Then
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&
 \frac{h_{\rm ref}\Psi(R_u)}{A}
 +\frac{G_0\Psi(R_u)}{p r_0}
 +\frac{32L_\gamma r_p^2}{A}\nonumber\\
 &+P_{\rm up}(p)\frac{\sigma_\gamma\mathcal H_p(R_u)}{\sqrt T}
 +\beta_\gamma(u).
 \label{eq:frontier-noise-risk}
\end{align}

\label{thm:frontier-pareto-lower}
Let any algorithm draw at most $n$ independent sampled functions and return
$\widehat x\in Q$, with the same known inputs and internal-randomization
law on both instances. Arbitrary adaptive query endpoints are allowed,
including observation of each entire realized sample function.
Suppose its deterministic-law guarantee is
\begin{equation}
 \mathbb E_0[m(S-\widehat x)]
 \le\frac{h_{\rm ref}\Psi(R_0)}{A}
 +\frac{m\Psi(R_0)}{p r_0}.
 \label{eq:frontier-affine-contract}
\end{equation}
Suppose also its rare-law guarantee, for some $P\ge0$, is
\begin{align}
 \mathbb E_1[f_1(\widehat x)-f_1(0)]\le{}&
 \frac{h_{\rm ref}\Psi(r_0)}{A}
 +\frac{m(1+1/n)\Psi(r_0)}{p r_0}\nonumber\\
 &+P\frac{\sigma_1\mathcal H_p(r_0)}{\sqrt n}.
 \label{eq:frontier-local-contract}
\end{align}
Writing $q_n=(1-1/n)^n$, necessarily
\begin{equation}
 P\ge\frac{[q_n(1+1/n)(1+p/5)-(2+1/n)/(2p)]_+}
                {2(2+1/p)}.
 \label{eq:frontier-exact-lower}
\end{equation}
In particular $P\ge p/88$ for $p\ge5$.

\label{lem:joint-offset-potential}
Condition on the complete anchor batch. For either admissible envelope
$\mathcal H(D)$ in \eqref{eq:joint-curvature-envelopes}, put
$\ell(D)=\log_2(1+\mathcal H(D)/h_{\rm ref})$.
For every conditionally fixed $w\in Q_S$,
\begin{align}
 \mathbb E[f(x_N)-f(w)\mid\text{anchor}]\le{}&
 \frac{h_{\rm a}\lVert w-x^0\rVert^2}{2A}
 +\left(\frac2A+\frac3{N^2}\right)D_S^2\mathcal H(D_S)
 +\frac{h_{\rm ref}D_S^2}{N^2}\nonumber\\
 &+\eta(D_S)[1+\ell(D_S)]
 +\frac{2MD_SN}{A}\ell(D_S).
 \label{eq:joint-conditional-risk}
\end{align}
For the smooth envelope replace the last term by
$LD_S^2\ell(D_S)/A$.

\label{lem:run5-distance-moment}
Under the preceding moment assumption,
\begin{equation}
 \mathbb E S^2\le S_2^2,\qquad \mathbb E S\le S_2<r_p.
 \label{eq:run5-distance-radius-moments}
\end{equation}

\label{lem:run5-distance-clipping}
If $f\le f_{\gamma_{\rm a}}$ and $f_{\gamma_{\rm a}}$ is convex, then
\begin{equation}
 \mathbb E\left[\frac{h_{\rm a}\lVert u_S-x^0\rVert^2}{2A}
       +f_{\gamma_{\rm a}}(u_S)-f(u)\right]\le\mathcal A_*(u).
 \label{eq:run5-distance-clipping-price}
\end{equation}
The same bound holds with $f(u_S)$ in place of
$f_{\gamma_{\rm a}}(u_S)$.

\label{thm:run5-distance-joint}
For a smooth population,
\begin{equation}
 \mathbb E[f(x_N)-f(u)]\le\mathcal A_*(u)
       +\mathcal U_{\rm s}(2S_2,\ell_{\rm s}^0).
 \label{eq:run5-distance-joint-smooth}
\end{equation}
If $\gamma_{\max}\ge2d^{1/4}r_p/N$, the nonsmooth branch satisfies
\begin{equation}
 \mathbb E[f(x_N)-f(u)]\le\mathcal A_*(u)
       +\mathcal U_{\rm ns}(2S_2,\ell_{\rm ns}^0).
 \label{eq:run5-distance-joint-nonsmooth}
\end{equation}
At every finite permitted evaluation radius it also satisfies
\begin{equation}
 \mathbb E[f(x_N)-f(u)]\le\mathcal A_*(u)+
 \min\{\mathcal U_{\rm ns}(2r_p,\ell_{\rm ns}^0),
             \mathcal V_{\rm ns}(S_2,\ell_{\rm ns}^0)\}.
 \label{eq:run5-distance-joint-finite-halo}
\end{equation}
With fixed batch sizes, $T\ge16N$ uses exactly $T$ pairs, $2T$ values, $3N+1$ sampling
stages and $N$ ball-intersection projections. With adaptive batch sizes, $T\ge32N$ gives
$5N+1$ stages and the same other counts.

\label{cor:run5-distance-stationary}
Under the smooth assumptions of Theorem~\ref{thm:run5-distance-joint},
\begin{equation}
 \mathbb E[f(x_N)-f(u)]\le\mathcal A_*^{\rm stat}(R_u)
       +\mathcal U_{\rm s}(2S_{R_u},\ell_{\rm s}^0).
 \label{eq:run5-distance-stationary-risk}
\end{equation}
If $\nabla f$ is affine on the evaluation domain, replace $G_{R_u}$ by $LR_u$ and $z_{R_u}$
by $\sqrt{L^2R_u^2+\sigma_{\rm a}^2/B_0}$ in these formulas. The smoothing
excess bound remains $L\nu_d\gamma_{\rm a}^2/2$.

\label{cor:run5-distance-reference-absorption}
Under Theorem~\ref{thm:run5-distance-joint}, for each applicable regularity case $\mathrm{reg}$, the saturated-price branch gives
\begin{align}
 \mathbb E[f(x_N)-f(u)]\le{}&
 \frac{z_{\rm a}\min\{R_u^2,r_p S_2\}}{2pr_0}
 +G_{\rm a}a_{R_u}+\beta_{\rm a}(u)
 +\mathcal J_{\mathrm{reg}}^0(S_2)
 +\frac{5h_{\rm ref}r_p^2}{N^2}.
 \label{eq:run5-distance-absorbed-risk}
\end{align}
For any target $\varepsilon>0$ chosen before sampling, the choice
$0<h_{\rm ref}\le\varepsilon N^2/(20r_p^2)$ makes the final term
at most $\varepsilon/4$. It needs no supplied original distance,
domain diameter, smoothness or variance.

\label{prop:run5-distance-curved}
The fixed-radius anchor optimizer satisfies
\begin{equation}
 v_1=x_1=q,\qquad v_t=0,\quad x_t=q/A_t\quad(2\le t\le N),
 \label{eq:run5-distance-quadratic-trajectory}
\end{equation}
and hence
\begin{equation}
 f_L(x_N)-f_L(u)=\frac L2(q/A-G/L)^2\ge\frac{Lq^2}{8A^2}.
 \label{eq:run5-distance-quadratic-risk}
\end{equation}
The joint radial controller has the same optimizer trajectory at every
selected legal radius. Vector and anchor variances are zero.

\label{cor:run5-distance-curved-transfer}
For this fixed-radius family there are no finite $C,E_0\ge0$ depending
only on the fixed known inputs and $G$ such that, uniformly in $L$,
\begin{equation}
 f_L(x_N)-f_L(u)\le\frac{h_{\rm ref}\Psi(R)}A+
 \frac{G\Psi(R)}{p r_0}+\frac{CLR^2}A+\beta_\gamma(u)+E_0.
 \label{eq:run5-distance-invalid-transfer}
\end{equation}
This remains false if $C$ is multiplied by any fixed polynomial in
$\log(1+L/h_{\rm ref})$.

\label{thm:prestep-potential}
Let $\phi$ be convex and differentiable on $Q$. For arbitrary vector
means and relative-value records define
\begin{equation}
 e_j=g_j-\nabla\phi(y_j),\qquad
 \zeta_j^q=\widehat q_j-[\phi(x_j^+)-\phi(y_j)],\qquad
 Z_j(u)=a_j\langle e_j,u-v^-\rangle-A_j^+\zeta_j^q .
 \label{eq:prestep-errors}
\end{equation}
For every fixed $u\in Q$, if $n$ trials have been accepted, then
\begin{equation}
 A_n[\phi(x_n)-\phi(u)]
       +\frac{h_0}{2}\lVert u-v_n\rVert^2
 \le\frac{h_0}{2}R_u^2
       +\sum_{j\in\mathcal A}\chi_j
       +\sum_{j\in\mathcal A}Z_j(u),
 \qquad R_u=\lVert u-x^0\rVert.
 \label{eq:prestep-pathwise-potential}
\end{equation}
If $\phi=f_\gamma\ge f$, the same fixed original comparator satisfies
\begin{align}
 A_n[f(x_n)-f(u)]+\frac{h_0}{2}\lVert u-v_n\rVert^2
 \le{}&\frac{h_0}{2}R_u^2+
       \sum_{j\in\mathcal A}[\chi_j+Z_j(u)]
       +A_n\beta_\gamma(u),\nonumber\\
 &\beta_\gamma(u)=f_\gamma(u)-f(u).
 \label{eq:prestep-original-potential}
\end{align}
The comparator need not minimize the smoothed population.

\label{cor:prestep-rare-price}
Under Theorem~\ref{thm:prestep-rare-curvature},
\begin{equation}
 \mathbb E[f_L(X_L)-f_L(x^\star)]
 \ge\frac3{64}\frac{w^2}{D^2}
                      \frac{\sigma_0D}{\sqrt T}.
 \label{eq:prestep-rare-diameter-price}
\end{equation}
If the deterministic linear instance satisfies
$\mathbb E[F_0(W)-\min_QF_0]\le GD/2$, the right side is at least
$3\sigma_0D/(256\sqrt T)$.
For fixed supplied inputs and any finite constant $C$, an algorithm
with $w>0$ cannot have, uniformly over this oracle family,
\begin{equation}
 \mathbb E[f_L(X_L)-f_L(x^\star)]
 \le C\left(\frac{(L+h_0)R^2}{N^2}
           +\frac{(\sigma_0+M_2)R}{\sqrt T}\right).
 \label{eq:prestep-pure-distance-template}
\end{equation}
Multiplying its right side by any fixed finite product of powers of
logarithms of $L,\sigma_0,M_2,R^{-1}$ also cannot restore this uniform
claim. A separate adaptation charge is necessary in the stated
unknown-scale finite-moment model.

\label{lem:preconf-weight-account}
For every record realization, let $n\le N$ be the number of accepted
trials and let $J_{\rm exec}\le K_{\rm tr}$ be the number executed.
Put $c=h_0/\mathcal L_0$. Then
\begin{align}
 A_n&\le cn^2,\nonumber\\
 \sum_{j\ {\rm executed}}a_j
 &\le A_n+2c+(2+\sqrt2)\sqrt{cA_n}\nonumber\\
 &\le c\bigl[N^2+(2+\sqrt2)N+2\bigr].
 \label{eq:preconf-weight-account}
\end{align}
These bounds include rejected trials and executions stopped before any acceptance.

\label{thm:preconf-error-contract}
Suppose that at every executed trial
\begin{equation}
 \lVert g_j-\nabla\phi(y_j)\rVert\le\eta_j^g,\qquad
 |\widehat q_j-[\phi(x_j^+)-\phi(y_j)]|
       \le\eta_j^q\lVert x_j^+-y_j\rVert.
 \label{eq:preconf-error-event}
\end{equation}
Put
\[
 J_\star=\lceil \log_2\max\{1,2L_\phi/\mathcal L_0\}\rceil,\qquad
 \overline{\mathcal L}=\max\{\mathcal L_0,4L_\phi\}.
\]
Every candidate at least $2L_\phi$ passes. There are at most $J_\star$
rejections and no candidate exceeds $\overline{\mathcal L}$.
If $K_{\rm tr}\ge N+J_\star$, the execution completes $N$ accepted
steps and $A_N\ge h_0N^2/(4\overline{\mathcal L})$.

Define $e_j=g_j-\nabla\phi(y_j)$,
$\zeta_j^q=\widehat q_j-[\phi(x_j^+)-\phi(y_j)]$, and
\[
 Z_j(u)=a_j\langle e_j,u-v^-\rangle-A_j^+\zeta_j^q.
\]
For every fixed $u\in Q$ and every accepted prefix,
\begin{equation}
 A_n[f(x_n)-f(u)]+\frac{h_0}{2}\lVert u-v_n\rVert^2
 \le\frac{h_0R_u^2}{2}
       +\sum_{j\ {\rm accepted}}(\chi_j+Z_j(u))
       +A_n\beta_\gamma(u).
 \label{eq:preconf-potential}
\end{equation}
If
\begin{equation}
 \eta_j=\min\left\{\frac{\varepsilon}{4D},
                 \sqrt{\frac{h_0\varepsilon}{4a_j}}\right\},
 \label{eq:preconf-tolerance}
\end{equation}
then the completed execution satisfies the unweighted bound
\begin{equation}
 f(x_N)-f(u)
 \le \frac{2\overline{\mathcal L}R_u^2}{N^2}
               +\frac{\varepsilon}{2}+\beta_\gamma(u).
 \label{eq:preconf-unweighted}
\end{equation}

\label{thm:preconf-paid-risk}
Under the stated moment assumptions and supplied upper bounds, this paired-oracle execution
has a simultaneous error event of probability at least $1-\delta_{\rm conf}$.
If $K_{\rm tr}\ge N+J_\star$, then for every fixed $u\in Q$ its
feasible returned point $\widehat x$ satisfies
\begin{equation}
 \mathbb E[f(\widehat x)-f(u)]
 \le\frac{2\overline{\mathcal L}R_u^2}{N^2}
       +\frac{\varepsilon}{2}+\beta_\gamma(u)+\delta_{\rm conf} MD.
 \label{eq:preconf-expected-risk}
\end{equation}
For every realization, the exact resources are
\begin{equation}
 T_{\rm exec}=k_{\rm mom}
       \sum_{j\ {\rm executed}}(b_j^g+b_j^q),\qquad
 2T_{\rm exec}\ \text{values},\quad
 2J_{\rm exec}\ \text{stages},\quad
 J_{\rm exec}\ \text{projections}.
 \label{eq:preconf-exact-resources}
\end{equation}
These counts include all rejected trials. The sample count satisfies
\begin{equation}
 T_{\rm exec}\le k_{\rm mom}\left[
 2J_{\rm exec}+\Lambda_{\rm mom}
 \sum_{j\ {\rm executed}}\max\left\{
       \frac{16D^2}{\varepsilon^2},
       \frac{4a_j}{h_0\varepsilon}\right\}\right].
 \label{eq:preconf-realized-budget}
\end{equation}
For every record realization, including incomplete executions,
\begin{equation}
 T_{\rm exec}\le k_{\rm mom}\left[
 2K_{\rm tr}+\frac{16\Lambda_{\rm mom}K_{\rm tr}D^2}{\varepsilon^2}
 +\frac{4\Lambda_{\rm mom}}{\mathcal L_0\varepsilon}
             [N^2+(2+\sqrt2)N+2]\right].
 \label{eq:preconf-public-budget}
\end{equation}
On the simultaneous event the stage and projection counts are at
most $2(N+J_\star)$ and $N+J_\star$, respectively.

\label{cor:observable-certification-no-cap}
Suppose \eqref{eq:observable-certification-validity} is required
uniformly over all laws with a finite second moment, and no upper
moment or range bound is supplied. Under the null law,
\begin{equation}
 \Pr_0(\tau<\infty,\widehat U<+\infty)\le\delta_{\rm conf}.
 \label{eq:observable-certification-no-cap}
\end{equation}
This holds even when $\tau$ has an unbounded distribution or infinite
expectation.

\label{lem:universal-distance-family}
Fix integers $T\ge2$, $N\ge1$, constants $D,L>0$, and $0<r<D$.
Let $Q=[0,D]$, $x^0=r$, and let the evaluation interval be
$I=[-D,2D]$. Define on the real line
\begin{equation}
 F_0(x)=\frac L2(x-D)^2,\qquad
 F_*(x)=F_0(x)+LDTx.
 \label{eq:universal-distance-samples}
\end{equation}
Under $\mathbb P_0$ every label returns $F_0$. Under $\mathbb P_1$
independent draws return $F_*$ with probability $1/T$ and $F_0$
otherwise. Both laws have the same supplied $Q,x^0,D,L,N,T$.
Their population objectives, stationary minimizers, original distances
and uniform centered gradient variances satisfy
\begin{align}
 f_0(x)&=\frac L2(x-D)^2,&x_0^\star&=D,&R_0&=D-r,&\sigma_0&=0,
 \nonumber\\
 f_1(x)&=\frac L2x^2+\frac L2D^2,&x_1^\star&=0,&R_1&=r,
 &\sigma_1^2&=L^2D^2(T-1).
 \label{eq:universal-distance-parameters}
\end{align}
All sample and population functions are convex and globally
$L$-smooth. On the open neighborhood $J=(-2D,3D)$ of $I$, both
populations admit the common Lipschitz bound $3LD$, and valid uniform
sample-gradient second-moment envelopes are
\begin{equation}
 M_{2,0}=3LD,\qquad M_{2,1}=LD\sqrt{T+8}.
 \label{eq:universal-distance-moments}
\end{equation}
The smallest uniform envelopes on the closed interval $I$ itself are
$2LD$ and $LD\sqrt{T+3}$.

\label{thm:universal-distance-menu}
For deterministic benchmarks $b_0,b_1>0$, the smallest factor $C$
for which one procedure can satisfy $\varepsilon_i\le Cb_i$ on both
laws is
\begin{equation}
 C_* =\frac{q_TLD^2}
 {2\bigl(\sqrt{b_1}+\sqrt{q_Tb_0}\bigr)^2}.
 \label{eq:universal-distance-menu-factor}
\end{equation}
The lower bound permits full-function access. A procedure that knows
the specified two-law family and both benchmark values attains this
factor using one sampling stage, exactly $T$ same-sample pairs and
$2T$ function values, one feasible output, and no projections or
optimizer restarts.

\label{cor:universal-distance-variance}
For
\[
 b_i^{\rm var}=\frac{LR_i^2}{N^2}
                    +\frac{\sigma_iR_i}{\sqrt T},
\]
every procedure satisfying $\varepsilon_i\le Cb_i^{\rm var}$ on
both laws, with $C\ge0$, must have
\begin{equation}
 C\ge\frac1{64}\min\{N^2,D/r\}.
 \label{eq:universal-distance-variance-price}
\end{equation}
For $0<r\le D/2$, the exact factor on the disclosed family obeys
\begin{equation}
 \frac1{64}\min\{N^2,D/r\}
 \le C_*^{\rm var}\le2\min\{N^2,D/r\}.
 \label{eq:universal-distance-variance-match}
\end{equation}

\label{cor:universal-distance-moment}
Assume $T\ge4$ and use the neighborhood envelopes in
\eqref{eq:universal-distance-moments}. For
\[
 b_i^{\rm mom}=\frac{LR_i^2}{N^2}
                    +\frac{M_{2,i}R_i}{\sqrt T},
\]
every procedure satisfying $\varepsilon_i\le Cb_i^{\rm mom}$ on
both laws, with $C\ge0$, must have
\begin{equation}
 C\ge\frac1{96}\min\{N^2,\sqrt T,D/r\}.
 \label{eq:universal-distance-moment-price}
\end{equation}
For $0<r\le D/2$, the exact competitive factor also satisfies
\begin{equation}
 C_*^{\rm mom}\le2\min\{N^2,\sqrt T,D/r\}.
 \label{eq:universal-distance-moment-match}
\end{equation}

\label{thm:learned-radius}\label{thm:protected-smoothing}
The specified variant spends exactly $T$ pairs and $2T$ values in
$5N$ sequential stages and uses $N$ projections. Define
\begin{align*}
 \mathcal S_N=\frac1{A_N}\sum_{t=1}^Nt\,
      \mathbb E[f_{\gamma_t}(x^\star)-f(x^\star)]&\le M\bar\gamma,\\
 L_*&=\sqrt d\,M/\underline\gamma.
\end{align*}
Its clean expected risk is at most
\begin{equation}
 \frac{h_0R^2}{2A_N}+\frac{16L_*D^2}{N^2}
       +\frac{8\sqrt2\sigma_0D}{\sqrt T}+\mathcal S_N.
 \label{eq:learned-clean}
\end{equation}
Under bounded value corruption, replace the stochastic term by
\[
 \frac{16\sigma_0D}{\sqrt T}
 +\frac{6c_dD\Delta}{\underline\gamma}
 +\frac{16dD\Delta}{\underline\gamma\sqrt T}.
\]
Here $\sigma_0^2$ uniformly bounds the clean single-record variance at
the selected radii. The full proof is in
Appendix~\ref{subsec:proof-learned-radius}.

\label{cor:resources}
There is a numerical constant $c$ such that, for any target
$\varepsilon>0$, Algorithm~\ref{alg:observed-radius} has expected gap
at most $\varepsilon$ whenever $\sigma_0^2\le CdM_2^2$ and the supplied
integer budgets satisfy
\begin{align}
 N&\ge c\left(1+\frac{\sqrt{h_0}R}{\sqrt\varepsilon}
 +\frac{d^{1/4}MD}{\varepsilon}
 +\frac{d^{1/4}D}{\gamma_{\max}}\right),\nonumber\\
 T&\ge c\left(N+d+\frac{CdM_2^2D^2}{\varepsilon^2}\right),
 \qquad \Delta\le\frac{\varepsilon}{c\,d^{1/4}N}.
 \label{eq:resource-conditions}
\end{align}
The cost is $5N$ sequential sampling stages and $2T$ scalar values.
The full proof is in Appendix~\ref{subsec:proof-resources}.

\label{cor:noise-frontier}
Let $T\in\mathbb N_+$, $\ell_T=\log(8(2T+1))$, $d\ge8\ell_T$,
$R,M>0$, and $0<\varepsilon\le MR/8$.
If
\begin{equation}
 \Delta\ge\frac{8\varepsilon\ell_T}{d}
   +\frac{16\sqrt2\varepsilon^2\sqrt{\ell_T}}{MR\sqrt d},
 \label{eq:noise-frontier-main}
\end{equation}
then every randomized method using at most $T$ original pairs has an
admissible convex $M$-Lipschitz instance on the ball $Q=R\mathbb B_2$
with $x^0=0$, initial solution distance $R$, and expected gap at least
$3\varepsilon/2$. The bound allows all sequential sampling schedules
and all query points in $\mathbb R^d$. The full proof is in
Appendix~\ref{subsec:proof-noise-frontier}.

\label{thm:startup-noise-price}
Let any algorithm draw at most $n$ independent sampled functions, choose arbitrary
adaptive query endpoints, and return $\widehat x\in Q$. Its supplied inputs
and internal-randomization law are the same on both instances. The result
also allows observation of the entire sample function under each label.
If for some $b_0\ge0$ its deterministic-instance gap satisfies
\begin{equation}
 \mathbb E_0[S-\widehat x]
 \le\frac{h_0(S-r_0)^2}{2A}+b_0
 =\frac{r_0A}{2}+b_0,
 \label{eq:startup-affine-contract}
\end{equation}
then
\begin{equation}
 \mathbb E_1[f_1(\widehat x)-f_1(0)]
 \ge(1-1/n)^n(1+1/n)[r_0(1+A/2)-b_0]_+.
 \label{eq:startup-affine-lower}
\end{equation}

\label{cor:startup-price}
Under Theorem~\ref{thm:startup-noise-price}, a proposed rare-instance
guarantee
\begin{equation}
 \mathbb E_1[f_1(\widehat x)-f_1(0)]
 \le\frac{h_0R^2}{2A}
 +P\frac{\sigma_1(R+r_0)}{\sqrt n},\qquad P\ge0,
 \label{eq:startup-local-contract}
\end{equation}
requires $P\ge A/32$ if the deterministic error bound
\eqref{eq:startup-affine-contract} has $b_0=0$.
Allowing $b_0\le r_0A/4$ still requires $P\ge A/64$.
In particular this applies with $n=T\ge8N$ and arbitrary adaptive
endpoints, even when the algorithm observes each full sample function.
